#include "hardwarestateprotocol.h"
#include "strictjson.h"
#include <set>
#include <stdexcept>
namespace GetDAQ {
namespace {
void Require(bool ok){if(!ok)throw std::invalid_argument("Invalid bounded live hardware observation");}
void Fields(const JsonValue &v,std::initializer_list<const char *> fields){Require(v.type==JsonValue::Object && v.members.size()==fields.size());for(const auto f:fields)v.At(f);}
std::string Text(const JsonValue &v,std::size_t maximum,bool empty=false){Require(v.type==JsonValue::String && v.text.size()<=maximum && (empty || !v.text.empty()));ValidateJsonUtf8(v.text);for(unsigned char c:v.text)Require(c>=32 && c!=127);return v.text;}
bool Boolean(const JsonValue &v){Require(v.type==JsonValue::Boolean);return v.text=="true";}
std::uint64_t Number(const JsonValue &v,bool quoted=false){Require(v.type==(quoted ? JsonValue::String : JsonValue::Number) && !v.text.empty() && v.text.size()<=20 && v.text.find_first_not_of("0123456789")==std::string::npos && (v.text.size()==1 || v.text.front()!='0'));std::uint64_t n=0;for(char c:v.text){Require(n<=(UINT64_MAX-unsigned(c-'0'))/10);n=n*10+unsigned(c-'0');}return n;}
std::string Digest(const JsonValue &v){const auto s=Text(v,64);Require(s.size()==64 && s.find_first_not_of("0123456789abcdef")==std::string::npos);return s;}
}
HardwareStateObservation DecodeHardwareStateObservation(const std::string &bytes){Require(bytes.size()<=1024*1024);const auto v=ParseStrictJson(bytes);Fields(v,{"schema","kind","instance_id","snapshot_sha256","configuration_sha256","artifact_sha256","controller_operation_id","controller_state","controller_outcome_unknown","controller_needs_reconciliation","busy","consistent","recovery_verified","actual_loaded_configuration_verified","global_control_verified","cobo_lifecycle_source","cobo_lifecycle_is_hardware_readback","cobo_lifecycle","nodes"});Require(Number(v.At("schema"))==1 && Text(v.At("kind"),80)=="getdaq.hardware-state-observation" && !Boolean(v.At("recovery_verified")) && !Boolean(v.At("actual_loaded_configuration_verified")) && !Boolean(v.At("global_control_verified")));
    HardwareStateObservation o;o.instanceId=Digest(v.At("instance_id"));o.snapshotSha256=Digest(v.At("snapshot_sha256"));o.configurationSha256=Digest(v.At("configuration_sha256"));o.artifactSha256=Digest(v.At("artifact_sha256"));o.controllerOperationId=Text(v.At("controller_operation_id"),128,true);const auto state=Number(v.At("controller_state"));Require(state>=1 && state<=6);o.controllerState=unsigned(state);o.controllerOutcomeUnknown=Boolean(v.At("controller_outcome_unknown"));o.controllerNeedsReconciliation=Boolean(v.At("controller_needs_reconciliation"));o.busy=Boolean(v.At("busy"));o.consistent=Boolean(v.At("consistent"));Require(!o.busy || !o.consistent);o.coboLifecycleSource=Text(v.At("cobo_lifecycle_source"),40);Require(o.coboLifecycleSource=="live-controller-cache" || o.coboLifecycleSource=="controller-baseline" || o.coboLifecycleSource=="unavailable");Require((o.consistent && !o.busy && o.coboLifecycleSource!="unavailable") || ((!o.consistent || o.busy) && o.coboLifecycleSource=="unavailable"));o.coboLifecycleIsHardwareReadback=Boolean(v.At("cobo_lifecycle_is_hardware_readback"));Require(!o.coboLifecycleIsHardwareReadback);const auto &lifecycle=v.At("cobo_lifecycle");Require(lifecycle.type==JsonValue::Array && lifecycle.items.size()<=192 && (o.consistent || lifecycle.items.empty()));std::set<std::string> lifecycleIds;
    for(const auto &entry:lifecycle.items){Fields(entry,{"id","state"});HardwareStateObservation::CoBoLifecycle item;item.id=Text(entry.At("id"),128);item.state=Text(entry.At("state"),16);Require(lifecycleIds.insert(item.id).second);Require(item.state=="fresh" || item.state=="preparing" || item.state=="prepared" || item.state=="configuring" || item.state=="configured" || item.state=="ready" || item.state=="starting" || item.state=="running" || item.state=="stopping" || item.state=="paused" || item.state=="resuming" || item.state=="stopped" || item.state=="unknown" || item.state=="disabled");o.coboLifecycle.push_back(item);}
    const auto &rows=v.At("nodes");Require(rows.type==JsonValue::Array && rows.items.size()<=195);std::set<std::string> ids;
    for(const auto &row:rows.items){Fields(row,{"id","role","available","message","observed_at_unix_ms","values"});HardwareStateObservation::Node n;n.id=Text(row.At("id"),128);n.role=Text(row.At("role"),16);Require(n.role=="cobo" || n.role=="mutant");Require(ids.insert(n.role+':'+n.id).second);n.available=Boolean(row.At("available"));n.message=Text(row.At("message"),1024,true);n.observedAtUnixMs=Number(row.At("observed_at_unix_ms"),true);const auto &values=row.At("values");Require(values.type==JsonValue::Object);const std::set<std::string> allowed=n.role=="cobo" ? std::set<std::string>{"firmwareEnable","intEnable","initDone","mutantMode"} : std::set<std::string>{"run"};Require(n.available ? values.members.size()==allowed.size() && n.observedAtUnixMs>0 : values.members.empty() && n.observedAtUnixMs==0);for(const auto &entry:values.members){Require(allowed.count(entry.first));const auto bit=Number(entry.second,true);Require(bit<=1);n.values[entry.first]=unsigned(bit);}Require((!o.busy && o.consistent) || !n.available);o.nodes.push_back(n);}
    if(!o.coboLifecycle.empty()){std::set<std::string> coboNodes;for(const auto &node:o.nodes)if(node.role=="cobo")coboNodes.insert(node.id);Require(coboNodes.size()==o.coboLifecycle.size());for(const auto &board:o.coboLifecycle)Require(coboNodes.count(board.id));}
    return o;
}
}
